ALTER TABLE SERVICO_SAUDE ADD (categoria VARCHAR2(15) DEFAULT 'ATENDIMENTO' NOT NULL);
ALTER TABLE SERVICO_SAUDE ADD CONSTRAINT ck_servico_categoria
  CHECK (categoria IN ('EXAME','ESPECIALIDADE','ATENDIMENTO'));

