FROM (
  SELECT '0025380' cnes, 'ESP_CARDIOLOGIA' cod, 'CNES_SR' fonte FROM dual
  UNION ALL SELECT '0025380' cnes, 'ESP_ENDOCRINOLOGIA' cod, 'CNES_SR' fonte FROM dual
