  UNION ALL SELECT '9997091' cnes, 'ESP_SAUDE_BUCAL' cod, 'CNES_SR' fonte FROM dual
  UNION ALL SELECT '9997091' cnes, 'EXAME_ELETROCARDIOGRAMA' cod, 'CNES_EQ' fonte FROM dual
  UNION ALL SELECT '9997091' cnes, 'EXAME_LABORATORIO' cod, 'CNES_SR' fonte FROM dual
  UNION ALL SELECT '9997091' cnes, 'EXAME_RAIO_X' cod, 'CNES_EQ' fonte FROM dual
) x
JOIN UNIDADE_SAUDE u ON u.codigo_cnes = x.cnes
JOIN SERVICO_SAUDE s ON s.codigo = x.cod
JOIN FONTE_DADO f ON f.sigla = x.fonte;
